import React from "react";
import { Routes, Route } from "react-router-dom";
import TopBar from "./TopBar";
import Orders from "./Orders";
import Holdings from "./Holdings";
import Positions from "./Positions";
import Funds from "./Funds";
import Apps from "./Apps";
import Summary from "./Summary"; // 🍏 In many setups, the main view is called Summary or Dashboard

const Home = () => {
  return (
    <div className="home-container">
      {/* 1. Renders your top panel layout containing user initials and logout tray */}
      <TopBar />

      <Routes>
        {/* 2. Map the root dashboard path to your Summary page view */}
        <Route path="/" element={<Summary />} />
        <Route path="/orders" element={<Orders />} />
        <Route path="/holdings" element={<Holdings />} />
        <Route path="/positions" element={<Positions />} />
        <Route path="/funds" element={<Funds />} />
        <Route path="/apps" element={<Apps />} />
      </Routes>
    </div>
  );
};

export default Home;
